"""보존된 실행기에서 경고 보정·DNS·Trace 독립 writer 기준을 준비한다."""
import hashlib,json,pathlib,shutil,subprocess
R=pathlib.Path(__file__).resolve().parents[1];W=R/'.worktrees/qg2runner'
def git(args,w=R):
 p=subprocess.run(['git','-C',str(w),*args],capture_output=True,timeout=45);assert p.returncode==0,p.stderr.decode('utf-8','replace');return p.stdout.decode('utf-8','replace').strip()
def save(path,text):path.parent.mkdir(parents=True,exist_ok=True);assert not path.exists(),path;path.write_text(text,encoding='utf-8',newline='\n')
assert not (R/'.harness/runs/qg2bstyle-qg2runner').exists()
git(['add','crates/network-core'],W);git(['-c','core.autocrlf=false','commit','-m','chore: preserve reviewed runner and verified adapter sync before style repair'],W);base=git(['rev-parse','HEAD'],W);assert not git(['status','--porcelain'],W)
for role in ['qgdns','qgtrace']:
 w=R/'.worktrees'/role;assert not w.exists();git(['worktree','add','-b','ai-pro/'+role,str(w),base]);refs=w/'.harness/references';refs.mkdir(parents=True,exist_ok=True)
 for name in ['qg2a-contract.json','qg2b-runner-contract.json']:shutil.copyfile(W/'.harness/references'/name,refs/name)
 if role=='qgdns':
  crate=w/'crates/network-resolver';(crate/'src').mkdir(parents=True);(crate/'tests').mkdir();source=R/'.harness/qa/g2wire-final/src/dns.rs';tests=R/'.harness/qa/g2wire-final/tests/dns.rs'
  save(crate/'Cargo.toml','[package]\nname = "network-resolver"\nversion.workspace = true\nedition.workspace = true\npublish = false\n\n[dependencies]\nserde.workspace = true\nserde_json.workspace = true\n')
  shutil.copyfile(source,crate/'src/lib.rs');text=tests.read_text(encoding='utf-8');assert '#[path = "../src/dns.rs"]\nmod dns;' in text;text=text.replace('#[path = "../src/dns.rs"]\nmod dns;','use network_resolver as dns;');save(crate/'tests/dns.rs',text)
  p=w/'Cargo.toml';s=p.read_text(encoding='utf-8');s=s.replace('"crates/network-core"]','"crates/network-core", "crates/network-resolver"]');p.write_text(s,encoding='utf-8',newline='\n')
  p=w/'crates/network-core/Cargo.toml';p.write_text(p.read_text(encoding='utf-8')+'\nnetwork-resolver = { path = "../network-resolver" }\n',encoding='utf-8',newline='\n')
  p=w/'crates/network-core/src/lib.rs';p.write_text(p.read_text(encoding='utf-8')+'\n// 기존 OS resolver 구현을 의존성 순환 없는 공용 crate로 재사용한다.\npub use network_resolver as dns_engine;\npub mod dns;\n',encoding='utf-8',newline='\n')
  provenance={'source':str(source),'sha256':hashlib.sha256(source.read_bytes()).hexdigest(),'method':'격리 검증한 DNS 구현 바이트를 공용 crate로 보존. 원 worktree는 역사 자료이며 제품 이중 구현 아님.','tests_original_sha256':hashlib.sha256(tests.read_bytes()).hexdigest(),'test_plumbing_only':'path mod dns replaced by use network_resolver as dns','actor_may_modify_engine':False};save(refs/'dns-engine-provenance.json',json.dumps(provenance,ensure_ascii=False,indent=2)+'\n')
  contract={'version':'qg2c-dns-0.1','scope':'기존 OS resolver 재사용·Quick 매핑. runner/GUI 연결은 후속이며 DNS 서버/RR/TTL 관찰 아님.','api':['pub fn dns_to_quick_result(ctx:&QuickContext,measurement:&dns_engine::DnsMeasurement)->Result<QuickResult,Vec<String>>','pub fn resolve_for_quick(ctx:&QuickContext,helper_executable:&std::path::Path,timeout:std::time::Duration,cancel:std::sync::Arc<std::sync::atomic::AtomicBool>)->Result<QuickResult,Vec<String>>'],'requirements':['기존 dns_engine의 실제 resolve API만 사용. 부모 자체 ToSocketAddrs 및 프로브 복제 금지.','host/port 불일치는 Err. raw trim·주소수리 금지. raw DTO와 전체 주소(max32) 보존. 실제 접속 선택은 후속 runner, lookup resolved_ip=null.','RESOLVED PASS/OBSERVED, DNS_ERROR·TIMED_OUT FAIL/OBSERVED, CANCELLED·LOCAL_ERROR UNKNOWN/UNKNOWN, 기타 UNKNOWN/UNKNOWN+한계. IP 리터럴은 DNS 호출0 명시.','timestamp/source/session/target/port/schema/product의 QG1 검증 준수. 불량 데이터 Err, JSON Schema 타입·필수 null 준수.','같은 EXE의 기존 WORKER_FLAG 분기로 OS resolver 실행 가능해야 함. 별도 배포 EXE·새 DNS 의존성 금지.','기본 시험은 순수 합성·process/network0. 실 worker 시험은 부모만 소유 localhost로 명시 실행.','공용 crate 준비는 부모 담당. actor는 dns.rs와 tests/dns.rs 두 파일만 작성.']};save(refs/'quick-dns-contract.json',json.dumps(contract,ensure_ascii=False,indent=2)+'\n')
 else:
  p=w/'crates/network-core/Cargo.toml';p.write_text(p.read_text(encoding='utf-8')+'\n[target.\'cfg(windows)\'.dependencies]\nwindows-sys = { version = "=0.61.2", features = ["Win32_Foundation", "Win32_Security", "Win32_System_JobObjects", "Win32_System_Threading", "Win32_System_Pipes", "Win32_System_SystemInformation"] }\n',encoding='utf-8',newline='\n')
  p=w/'crates/network-core/src/lib.rs';p.write_text(p.read_text(encoding='utf-8')+'\npub mod traceroute;\n',encoding='utf-8',newline='\n')
  contract={'version':'qg2c-trace-0.1','api':['pub struct TraceOptions { pub max_hops:u8, pub probe_timeout_ms:u32, pub overall_timeout_ms:u64 }','impl Default for TraceOptions (max_hops=30,probe_timeout_ms=1000,overall_timeout_ms=30000)','pub struct TraceHop { pub ttl:u8,pub address:Option<String>,pub probe_times_ms:Vec<Option<u32>>,pub rtt_less_than:Vec<bool>,pub raw_line:String }','pub struct TraceMeasurement { pub target:String,pub method:String,pub outcome:String,pub hops:Vec<TraceHop>,pub elapsed_ms:u64,pub exit_code:Option<i32>,pub raw_stdout:Vec<u8>,pub raw_stderr:Vec<u8>,pub output_truncated:bool,pub limitations:Vec<String> }','pub fn parse_trace_output(target:std::net::IpAddr,output:&[u8],max_hops:u8)->Result<Vec<TraceHop>,Vec<String>>','pub fn trace_once(target:std::net::IpAddr,options:&TraceOptions,cancel:std::sync::Arc<std::sync::atomic::AtomicBool>)->TraceMeasurement','pub fn trace_to_quick_result(ctx:&QuickContext,measurement:&TraceMeasurement)->Result<QuickResult,Vec<String>>'],'requirements':['GetSystemDirectoryW의 절대 System32 tracert.exe만 Command::new로 실행. shell/PATH/cwd 탐색 금지. -d/-4 또는 -6/-h/-w와 typed IP만 전달. 도메인/임의 명령/OS 변경 금지. 비Windows는 UNAVAILABLE/native0.','CREATE_NO_WINDOW, JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE. Job 할당 실패 fail-closed. stdout/stderr 각32KiB·초과 명시. try_wait+10ms poll, 전체 timeout/취소 kill·회수, OS 실패 한계 기록.','reader thread 무한 join 금지. PeekNamedPipe로 가용량만 읽고 종료 후 잔량 drain. 자식 cleanup 실패를 숨기지 않음.','raw stdout/stderr bytes 보존. ASCII 숫자/IP 중심 파싱, 로케일 헤더/완료 문자열로 성공 판정 금지. TTL 순서·3samples·IPv4/IPv6 검증. <1ms는 값1+less_than=true 상한 표시, *는 None. 비응답=차단 단정 금지.','중복/범위외 TTL·불량 hop은 parse error. 완전한 행만 hops, 부분·파싱실패 raw 보존. IP trim 수리 금지.','최종 대상 IP 응답만 REACHED, 비응답/최대hop은 INCOMPLETE. 불량 파싱 PARSE_ERROR. TIMED_OUT/CANCELLED/LOCAL_ERROR/UNAVAILABLE PASS 금지. Instant 실측, 가짜 RTT/hop 금지.','Quick:REACHED PASS/OBSERVED, INCOMPLETE 유효hop 있으면 WARN/OBSERVED 아니면 UNKNOWN/UNKNOWN. PARSE_ERROR/TIMED_OUT/CANCELLED/LOCAL_ERROR/UNAVAILABLE UNKNOWN/UNKNOWN. resolved_ip literal 일치·ctx 불일치 Err. raw_measurement 전체·한계 보존.','options max_hops1..30, probe_timeout_ms1..2000, overall_timeout_ms1..60000 무보정 검증. 불량 옵션/대상(unspecified,multicast,broadcast,영역 없는 linklocal)과 사전취소는 spawn0.','기본 시험은 합성 parser/adapter/검증만, process/network0. 실제 소유 IPv4/IPv6 loopback은 #[ignore]로 부모만 실행.','TCP/Ping 프로브 복제 금지. 두 파일만 작성, runner/manifest/core enum/Inspector 변경 금지. 한국어 주석·UTF8, Clippy suppression 금지.'],'official_references':['https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/tracert','https://learn.microsoft.com/en-us/windows/win32/procthread/job-objects']};save(refs/'quick-trace-contract.json',json.dumps(contract,ensure_ascii=False,indent=2)+'\n')
 # 대상 모듈은 actor가 작성하므로 부모는 metadata만 준비한다.
 p=subprocess.run(['cargo','metadata','--offline','--filter-platform','x86_64-pc-windows-msvc','--no-deps','--format-version','1'],cwd=w,capture_output=True,timeout=30);assert p.returncode==0,p.stderr.decode('utf-8','replace')
 git(['add','Cargo.toml','Cargo.lock','crates'],w);git(['-c','core.autocrlf=false','commit','-m','chore: prepare isolated '+role+' contract and shared dependencies'],w);assert not git(['status','--porcelain'],w)
print(json.dumps({'base':base,'roles':['qg2runner','qgdns','qgtrace'],'worktrees_isolated':True},ensure_ascii=False))
